function k(t){let y=t>65535?new Uint32Array(t):new Uint16Array(t);for(let l=0;l<t;l++)y[l]=l;return y}function B(t,y,l){let n=new Float32Array(l*3),z=y.length>0,q=z?y.length/3|0:l/3|0;for(let c=0;c<q;c++){let a=z?y[c*3]:c*3,e=z?y[c*3+1]:c*3+1,r=z?y[c*3+2]:c*3+2,o=t[a*3],m=t[a*3+1],x=t[a*3+2],F=t[e*3],I=t[e*3+1],M=t[e*3+2],N=t[r*3],d=t[r*3+1],j=t[r*3+2],w=F-o,A=I-m,g=M-x,u=N-o,S=d-m,U=j-x,f=A*U-g*S,h=g*u-w*U,b=w*S-A*u;n[a*3]+=f,n[a*3+1]+=h,n[a*3+2]+=b,n[e*3]+=f,n[e*3+1]+=h,n[e*3+2]+=b,n[r*3]+=f,n[r*3+1]+=h,n[r*3+2]+=b}for(let c=0;c<l;c++){let a=n[c*3],e=n[c*3+1],r=n[c*3+2],o=Math.hypot(a,e,r)||1;n[c*3]=a/o,n[c*3+1]=e/o,n[c*3+2]=r/o}return n}export{B as computeSmoothNormals,k as createSequentialIndices};
